import java.util.Scanner;

public class Main {
    static long[] pattern = new long[20];
    static int minSteps;

    static long getLeading(long num, int[] length) {
        length[0] = 0;
        while (num >= 10) {
            num /= 10;
            length[0]++;
        }
        return num;
    }

    static void search(long currentValue, int stepsTaken) {
        if (stepsTaken >= minSteps) return;
        if (currentValue == 0) {
            minSteps = stepsTaken;
            return;
        }
        int[] lenArr = new int[1];
        int leadDigit = (int) getLeading(currentValue, lenArr);
        int len = lenArr[0];

        search(Math.abs(currentValue - pattern[len] * leadDigit), stepsTaken + leadDigit * (len + 1));
        if (leadDigit - 1 > 0)
            search(Math.abs(currentValue - pattern[len] * (leadDigit - 1)), stepsTaken + (leadDigit - 1) * (len + 1));
        if (leadDigit > 1)
            search(Math.abs(pattern[len + 1] - currentValue), stepsTaken + (len + 2));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        pattern[0] = 1;
        for (int i = 1; i <= 18; i++) {
            pattern[i] = pattern[i - 1] * 10 + 1;
        }
        minSteps = Integer.MAX_VALUE;
        search(n, 0);
        System.out.println(minSteps);
        sc.close();
    }
}
